<?php
/**
 * Cong cu tu dong khac phuc loi & Cap nhat Theme Muop Dang 1 Cham
 * Danh cho Hosting: muopdangcungcovingot.io.vn
 */
header('Content-Type: text/html; charset=utf-8');

$b64_header = '';
$b64_story_card = '';

$results = [];
$errors = [];

// Tim thu muc goc website & thu muc theme
$base_dir = __DIR__;
$wp_load_candidates = [
    $base_dir . '/wp-load.php',
    $base_dir . '/core/wp-load.php',
    dirname($base_dir) . '/wp-load.php',
    dirname($base_dir) . '/core/wp-load.php',
];

$wp_load_path = null;
foreach ($wp_load_candidates as $cand) {
    if (file_exists($cand)) {
        $wp_load_path = $cand;
        break;
    }
}

$theme_dir_candidates = [
    $base_dir . '/wp-content/themes/muop-dang',
    dirname($base_dir) . '/wp-content/themes/muop-dang',
    $base_dir . '/core/wp-content/themes/muop-dang',
    $base_dir . '/themes/muop-dang',
];

$theme_dir = null;
foreach ($theme_dir_candidates as $cand) {
    if (is_dir($cand)) {
        $theme_dir = $cand;
        break;
    }
}

$action = isset($_GET['action']) ? $_GET['action'] : '';

// Xu ly tu xoa file
if ($action === 'delete_self') {
    @unlink(__FILE__);
    echo '<div style="font-family:sans-serif;text-align:center;padding:50px;"><h2>Đã xóa file khac_phuc_loi.php an toàn!</h2><p><a href="/">Quay lại Trang Chủ</a></p></div>';
    exit;
}

// 1. Tu dong sua file header.php va story-card.php
if ($action === 'fix_header' || $action === 'auto_all') {
    if ($theme_dir && is_dir($theme_dir)) {
        $target_header = $theme_dir . '/header.php';
        $content = base64_decode($b64_header);
        if (@file_put_contents($target_header, $content)) {
            $results[] = 'Đã cập nhật đè file <code>header.php</code> phiên bản mới (bảo vệ chống Fatal Error 100%) vào: ' . $target_header;
        } else {
            $errors[] = 'Không thể ghi vào file ' . $target_header . '. Hãy kiểm tra phân quyền thư mục (CHMOD 755 hoặc 644).';
        }

        $target_sc = $theme_dir . '/template-parts/story-card.php';
        $sc_dir = dirname($target_sc);
        if (!is_dir($sc_dir)) @mkdir($sc_dir, 0755, true);
        $sc_content = base64_decode($b64_story_card);
        if (@file_put_contents($target_sc, $sc_content)) {
            $results[] = 'Đã cập nhật đè file <code>story-card.php</code> (sửa triệt để muop_can_see_story_views) vào: ' . $target_sc;
        }
    } else {
        $errors[] = 'Không tìm thấy thư mục theme muop-dang!';
    }
}

// 2. Tu dong giai nen file ZIP neu co tren server
if ($action === 'unzip_all' || $action === 'auto_all') {
    $zip_files = glob($base_dir . '/*.zip');
    $zip_files = array_merge($zip_files, glob($base_dir . '/wp-content/themes/*.zip'));
    
    $extracted_count = 0;
    if (class_exists('ZipArchive') && !empty($zip_files)) {
        foreach ($zip_files as $zf_path) {
            $bname = basename($zf_path);
            if (strpos($bname, 'muop') !== false || strpos($bname, 'cap_nhat') !== false) {
                $zip = new ZipArchive();
                if ($zip->open($zf_path) === TRUE) {
                    $dest = $theme_dir;
                    if (strpos($bname, 'goc_website') !== false) {
                        $dest = $base_dir;
                    } elseif (strpos($bname, 'muop-dang.zip') !== false) {
                        $dest = dirname($theme_dir);
                    }
                    
                    if ($dest && is_dir($dest)) {
                        $zip->extractTo($dest);
                        $zip->close();
                        $results[] = 'Đã giải nén thành công gói <strong>' . $bname . '</strong> vào <code>' . $dest . '</code>!';
                        $extracted_count++;
                    }
                }
            }
        }
    }
    if ($extracted_count === 0 && ($action === 'unzip_all' || $action === 'auto_all')) {
        $results[] = 'Không tìm thấy file zip nào trong thư mục gốc để giải nén. Bạn có thể tải lên gói zip rồi nhấn lại nút này.';
    }
}

// 3. Nap thu WordPress va don dep cache
$wp_loaded = false;
if ($wp_load_path) {
    try {
        require_once $wp_load_path;
        $wp_loaded = true;
        
        if (function_exists('delete_transient')) {
            delete_transient('muop_all_genres_list');
            $results[] = 'Đã xóa transient cache giao diện thành công!';
        }
        if (function_exists('flush_rewrite_rules')) {
            flush_rewrite_rules(false);
            $results[] = 'Đã làm mới quy tắc điều hướng (Rewrite rules) thành công!';
        }
    } catch (Throwable $e) {
        $errors[] = 'Lỗi nạp WordPress: ' . $e->getMessage();
    }
}
?>
<!DOCTYPE html>
<html lang="vi">
<head>
    <meta charset="UTF-8">
    <title>Khắc Phục Lỗi & Cập Nhật Mướp Đắng</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #f4f6f8; color: #2d3748; padding: 20px; margin: 0; }
        .box { max-width: 760px; margin: 30px auto; background: #fff; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.08); overflow: hidden; }
        .header { background: #406b47; color: white; padding: 24px 30px; }
        .header h1 { margin: 0 0 8px; font-size: 22px; }
        .header p { margin: 0; opacity: 0.9; font-size: 14px; }
        .content { padding: 30px; }
        .btn { display: inline-block; padding: 12px 20px; font-size: 15px; font-weight: 600; color: white; background: #406b47; border-radius: 8px; text-decoration: none; border: none; cursor: pointer; transition: 0.2s; }
        .btn:hover { background: #2f5235; }
        .btn-danger { background: #e53e3e; }
